type StructName = (typeof STRUCT_NAMES)[number];
type SupportedRustType = "String" | "u32";

interface RustField {
  name: string;
  rustType: SupportedRustType;
}

function fail(detail: string): never {
  throw new Error(`echo codegen: ${detail}`);
}

/** Normalize generated bytes before freshness comparison and transport stamping. */
function formatGenerated(source: string, destination: string): string {
  const result = Bun.spawnSync(
    [process.execPath, "fmt", "--no-script", "--stdin-filepath", destination],
    { cwd: repositoryRoot, stdin: Buffer.from(source) },
  );
  if (result.exitCode !== 0) fail(`native formatting failed: ${result.stderr}`);
  return result.stdout.toString();
}

function parseStruct(lines: readonly string[], name: StructName): RustField[] {
  const declaration = new RegExp(`^\\s*pub\\s+struct\\s+${name}\\b`);
  const candidates = lines
    .map((line, index) => ({ line, index }))
    .filter(({ line }) => declaration.test(line));

  if (candidates.length === 0)
    fail(`missing public ${name} struct in crates/keld-ipc/src/echo.rs`);
  if (candidates.length !== 1)
    fail(`duplicate public ${name} struct declarations`);

  const [{ line: opening, index: start }] = candidates;
  if (opening !== `pub struct ${name} {`) {
    fail(`${name} must use the rustfmt-normalized named public-field form`);
  }

  const fields: RustField[] = [];
  const names = new Set<string>();
  for (let index = start + 1; index < lines.length; index += 1) {
    const line = lines[index];
    if (line === "}") {
      if (fields.length === 0)
        fail(`${name} must contain at least one public field`);
      return fields;
    }
    if (line.length === 0 || /^    \/\/\/(?: |$)/.test(line)) continue;

    const field =
      /^    pub ([A-Za-z_][A-Za-z0-9_]*): ([A-Za-z_][A-Za-z0-9_:<>]*),$/.exec(
        line,
      );
    if (!field) {
      fail(
        `${name} contains unsupported body syntax on source line ${index + 1}: ${line.trim()}`,
      );
    }
    const [, fieldName, rustType] = field;
    if (rustType !== "String" && rustType !== "u32") {
      fail(
        `${name}.${fieldName} uses unsupported Rust type ${rustType}; supported: String, u32`,
      );
    }
    if (!names.add(fieldName))
      fail(`${name} contains duplicate field ${fieldName}`);
    fields.push({ name: fieldName, rustType });
  }

  return fail(`unterminated public ${name} struct`);
}

function renderField(field: RustField): string[] {
  if (field.rustType === "String") return [`  ${field.name}: string;`];
  return [
    "  /** Rust u32 domain: integer in 0..=4_294_967_295; runtime bounds stay in the postcard codec. */",
    `  ${field.name}: number;`,
  ];
}

/** Renders the bounded echo declarations from their canonical Rust structs. */
export function renderEchoDeclarations(
  rustSource: string,
  destination: string = generatedPaths[0],
): string {
  const lines = rustSource.replaceAll("\r\n", "\n").split("\n");
  const output = [
    "// @generated by packages/@keld/kipc/scripts/echo-codegen.ts.",
    "// Source: crates/keld-ipc/src/echo.rs. Do not edit by hand.",
    "",
  ];

  for (const name of STRUCT_NAMES) {
    output.push(`export interface ${name} {`);
    for (const field of parseStruct(lines, name))
      output.push(...renderField(field));
    output.push("}", "");
  }
  return formatGenerated(output.join("\n"), destination);
}

/** Fails when checked-in bytes do not exactly match the canonical Rust source. */
export function assertEchoArtifactFresh(
  rustSource: string,
  artifact: Uint8Array,
  destination: string = generatedPaths[0],
): void {
  const expected = Buffer.from(
    renderEchoDeclarations(rustSource, destination),
    "utf8",
  );
  if (!Buffer.from(artifact).equals(expected)) {
    fail("committed echo.generated.ts is stale; run bun run echo:generate");
  }
}

// Native enum declaration grammar is shared; each target admits its own closed schema.
type NativeEnumName =
  "FsRequest" | "FsResponse" | "AuthRequest" | "AuthResponse";
type NativeFieldType =
  | "String"
  | "Vec<u8>"
  | "Vec<String>"
  | "Option<String>"
  | "Option<Vec<String>>"
  | "u64";
interface NativeField {
  name: string;
  rustType: NativeFieldType;
}
interface NativeVariant {
  name: string;
  fields: NativeField[];
}
type NativeSchema = Readonly<
  Record<string, Readonly<Record<string, NativeFieldType>>>
>;

const NATIVE_SCHEMAS: Readonly<Record<NativeEnumName, NativeSchema>> = {
  FsRequest: {
    Read: { path: "String" },
    Write: { path: "String", bytes: "Vec<u8>" },
  },
  FsResponse: { Read: { bytes: "Vec<u8>" }, Write: {} },
  AuthRequest: {
    Begin: {
      provider: "String",
      scopes: "Option<Vec<String>>",
      login_hint: "Option<String>",
    },
    Token: { account_id: "String", scopes: "Option<Vec<String>>" },
  },
  AuthResponse: {
    Begin: { account_id: "String", granted_scopes: "Vec<String>" },
    Token: { access_token: "String", expires_at: "u64", token_type: "String" },
  },
};

function parseNativeEnum(
  lines: readonly string[],
  name: NativeEnumName,
): NativeVariant[] {
  const declaration = new RegExp(
    "^\\s*(?:pub(?:\\([^)]*\\))?\\s+)?enum\\s+" + name + "\\b",
  );
  const starts = lines.flatMap((line, index) =>
    declaration.test(line) ? [index] : [],
  );
  if (starts.length !== 1)
    fail("native " + name + " requires exactly one public enum declaration");
  const start = starts[0];
  if (lines[start] !== "pub enum " + name + " {")
    fail("native " + name + " must use the rustfmt-normalized named enum form");
  let derives = 0;
  for (let index = start - 1; index >= 0; index -= 1) {
    const line = lines[index];
    if (line.length === 0 || /^\/\/\/(?: |$)/.test(line)) continue;
    if (line.startsWith("#[")) {
      if (
        !/^#\[derive\((?:(?:Debug|Clone), )?Serialize, Deserialize\)\]$/.test(
          line,
        )
      ) {
        fail(
          "native " +
            name +
            " has unsupported enum attribute on source line " +
            (index + 1),
        );
      }
      derives += 1;
      continue;
    }
    if (line === "}" || line.endsWith(";")) break;
    fail(
      "native " +
        name +
        " has unsupported declaration prefix on source line " +
        (index + 1),
    );
  }
  if (derives !== 1)
    fail(
      "native " + name + " requires one admitted Serialize/Deserialize derive",
    );
  const schema = NATIVE_SCHEMAS[name];
  const variants: NativeVariant[] = [];
  for (let index = start + 1; index < lines.length; index += 1) {
    const line = lines[index];
    if (line === "}") {
      if (variants.length !== Object.keys(schema).length)
        fail("native " + name + " variants differ from its closed schema");
      for (const variant of variants) {
        const expected = schema[variant.name];
        if (
          variant.fields.length !== Object.keys(expected).length ||
          variant.fields.some(
            (field) => expected[field.name] !== field.rustType,
          )
        ) {
          fail(
            "native " +
              name +
              "::" +
              variant.name +
              " fields differ from the admitted schema",
          );
        }
      }
      return variants;
    }
    if (line.length === 0 || /^    \/\/\/(?: |$)/.test(line)) continue;
    const opening = /^    ([A-Z][A-Za-z0-9_]*)( \{|,)$/.exec(line);
    if (!opening || !Object.hasOwn(schema, opening[1])) {
      fail(
        "native " +
          name +
          " contains unsupported variant syntax on source line " +
          (index + 1),
      );
    }
    const variantName = opening[1];
    if (variants.some((variant) => variant.name === variantName))
      fail("native " + name + " has duplicate " + variantName);
    const fields: NativeField[] = [];
    if (opening[2] === " {") {
      let closed = false;
      for (index += 1; index < lines.length; index += 1) {
        const fieldLine = lines[index];
        if (fieldLine === "    },") {
          closed = true;
          break;
        }
        if (fieldLine.length === 0 || /^        \/\/\/(?: |$)/.test(fieldLine))
          continue;
        const field =
          /^        ([A-Za-z_][A-Za-z0-9_]*): (String|Vec<u8>|Vec<String>|Option<String>|Option<Vec<String>>|u64),$/.exec(
            fieldLine,
          );
        if (!field)
          fail(
            "native " +
              name +
              "::" +
              variantName +
              " has unsupported field syntax on source line " +
              (index + 1),
          );
        if (fields.some((candidate) => candidate.name === field[1]))
          fail(
            "native " +
              name +
              "::" +
              variantName +
              " has duplicate field " +
              field[1],
          );
        fields.push({ name: field[1], rustType: field[2] as NativeFieldType });
      }
      if (!closed || fields.length === 0)
        fail(
          "native " +
            name +
            "::" +
            variantName +
            " must have a nonempty named body",
        );
    }
    variants.push({ name: variantName, fields });
  }
  return fail("unterminated native " + name);
}

/** Renders the one bounded native FS payload binding; Rust owns all variant/field order. */
export function renderFsBinding(rustSource: string): string {
  const lines = rustSource.replaceAll("\r\n", "\n").split("\n");
  if (lines.some((line) => /^\s*#!\[/.test(line)))
    fail("native FS source-level attributes are not admitted");
  const request = parseNativeEnum(lines, "FsRequest");
  const response = parseNativeEnum(lines, "FsResponse");
  const output = [
    "// @generated by packages/@keld/kipc/scripts/echo-codegen.ts.",
    "// Source: crates/keld-native/src/fs.rs. Do not edit by hand.",
    "",
    'import { MAX_FRAME_LEN, decodeVarint, encodeVarint, encodePostcardString, kipcError } from "../../kipc/src/transport.ts";',
    "",
  ];
  for (const [name, variants] of [
    ["FsRequest", request],
    ["FsResponse", response],
  ] as const) {
    output.push(`export type ${name} =`);
    for (const variant of variants) {
      const fields = variant.fields
        .map(
          (field) =>
            `; ${field.name}: ${field.rustType === "String" ? "string" : "Uint8Array"}`,
        )
        .join("");
      output.push(
        `  | { variant: "${variant.name}"${fields} }${variant === variants[variants.length - 1] ? ";" : ""}`,
      );
    }
    output.push("");
  }
  output.push(
    "function encodeBytes(value: Uint8Array): Uint8Array {",
    '  if (!(value instanceof Uint8Array)) throw kipcError("KELD-IPC-003", "FsRequest.bytes must be a Uint8Array");',
    "  const length = encodeVarint(value.byteLength);",
    '  if (length.length + value.byteLength > MAX_FRAME_LEN) throw kipcError("KELD-IPC-003", "FS payload exceeds MAX_FRAME_LEN");',
    "  const encoded = new Uint8Array(length.length + value.byteLength);",
    "  encoded.set(length);",
    "  encoded.set(value, length.length);",
    "  return encoded;",
    "}",
    "",
    "function joinPayload(parts: readonly Uint8Array[]): Uint8Array {",
    "  const length = parts.reduce((total, part) => total + part.byteLength, 0);",
    '  if (length > MAX_FRAME_LEN) throw kipcError("KELD-IPC-003", "FS payload exceeds MAX_FRAME_LEN");',
    "  const payload = new Uint8Array(length);",
    "  let offset = 0;",
    "  for (const part of parts) { payload.set(part, offset); offset += part.byteLength; }",
    "  return payload;",
    "}",
    "",
    "/** Encodes and snapshots a native request in Rust declaration order. */",
    "export function encodeFsRequest(value: FsRequest): Uint8Array {",
    '  if (!value || typeof value !== "object") throw kipcError("KELD-IPC-003", "FsRequest must be an object");',
    "  switch (value.variant) {",
  );
  request.forEach((variant, index) => {
    const fields = variant.fields.map((field) =>
      field.rustType === "String"
        ? `encodePostcardString(value.${field.name}, "FsRequest.${field.name}")`
        : `encodeBytes(value.${field.name})`,
    );
    output.push(
      `    case "${variant.name}": return joinPayload([encodeVarint(${index}), ${fields.join(", ")}]);`,
    );
  });
  output.push(
    '    default: throw kipcError("KELD-IPC-003", "unknown FsRequest variant");',
    "  }",
    "}",
    "",
    "/** Decodes an exact native response; returned content owns an independent copy. */",
    "export function decodeFsResponse(payload: Uint8Array): FsResponse {",
    '  if (!(payload instanceof Uint8Array)) throw kipcError("KELD-IPC-003", "FsResponse payload must be a Uint8Array");',
    "  const [variant, afterVariant] = decodeVarint(payload, 0);",
    "  let offset = afterVariant;",
    "  let response: FsResponse;",
    "  switch (variant) {",
  );
  response.forEach((variant, index) => {
    output.push(`    case ${index}: {`);
    for (const field of variant.fields) {
      // Only response byte vectors are admitted by parseNativeEnum's current schema.
      output.push(
        `      const [${field.name}Length, afterLength] = decodeVarint(payload, offset);`,
        `      const end = afterLength + ${field.name}Length;`,
        '      if (end > payload.byteLength) throw kipcError("KELD-IPC-003", "FsResponse byte length does not match payload");',
        `      const ${field.name} = new Uint8Array(payload.subarray(afterLength, end));`,
        "      offset = end;",
      );
    }
    output.push(
      `      response = { variant: "${variant.name}"${variant.fields.map((field) => `, ${field.name}`).join("")} };`,
      "      break;",
      "    }",
    );
  });
  output.push(
    '    default: throw kipcError("KELD-IPC-003", "unknown FsResponse variant");',
    "  }",
    '  if (offset !== payload.byteLength) throw kipcError("KELD-IPC-003", "trailing bytes after FsResponse");',
    "  return response;",
    "}",
    "",
  );
  return formatGenerated(output.join("\n"), fsGeneratedPath);
}

/** Requires byte-exact generated FS binding freshness against the native enums. */
export function assertFsArtifactFresh(
  rustSource: string,
  artifact: Uint8Array,
): void {
  if (
    !Buffer.from(artifact).equals(
      Buffer.from(renderFsBinding(rustSource), "utf8"),
    )
  ) {
    fail("committed fs.generated.ts is stale; run bun run echo:generate");
  }
}

const AUTH_RUNTIME =
  'function appendPart(parts: Uint8Array[], part: Uint8Array, length: number): number {\n  const total = length + part.byteLength;\n  if (total > MAX_FRAME_LEN) throw kipcError("KELD-IPC-003", "auth payload exceeds MAX_FRAME_LEN");\n  parts.push(part);\n  return total;\n}\n\nfunction encodeStringVector(value: readonly string[], field: string): Uint8Array {\n  if (!Array.isArray(value)) throw kipcError("KELD-IPC-003", field + " must be a string array");\n  const parts: Uint8Array[] = [encodeVarint(value.length)];\n  let length = parts[0].byteLength;\n  for (const item of value) length = appendPart(parts, encodePostcardString(item, field), length);\n  return Buffer.concat(parts, length);\n}\n\nfunction encodeOptionalString(value: string | null, field: string): Uint8Array {\n  if (value === null) return new Uint8Array([0]);\n  const encoded = encodePostcardString(value, field);\n  if (encoded.byteLength + 1 > MAX_FRAME_LEN) throw kipcError("KELD-IPC-003", "auth payload exceeds MAX_FRAME_LEN");\n  return Buffer.concat([new Uint8Array([1]), encoded]);\n}\n\nfunction encodeOptionalScopes(value: readonly string[] | null, field: string): Uint8Array {\n  if (value === null) return new Uint8Array([0]);\n  const encoded = encodeStringVector(value, field);\n  if (encoded.byteLength + 1 > MAX_FRAME_LEN) throw kipcError("KELD-IPC-003", "auth payload exceeds MAX_FRAME_LEN");\n  return Buffer.concat([new Uint8Array([1]), encoded]);\n}\n\nfunction decodeStringVector(payload: Uint8Array, start: number): [readonly string[], number] {\n  const [length, afterLength] = decodeVarint(payload, start);\n  if (length > payload.byteLength - afterLength) throw kipcError("KELD-IPC-003", "auth string vector cannot fit payload");\n  const values: string[] = [];\n  let offset = afterLength;\n  for (let index = 0; index < length; index += 1) {\n    const [value, next] = decodePostcardStringAt(payload, offset);\n    values.push(value);\n    offset = next;\n  }\n  return [values, offset];\n}\n\n';

function authFieldTsType(field: NativeField): string {
  switch (field.rustType) {
    case "String":
      return "string";
    case "Vec<String>":
      return "readonly string[]";
    case "Option<Vec<String>>":
      return "readonly string[] | null";
    case "Option<String>":
      return "string | null";
    case "u64":
      return "bigint";
    default:
      return fail("unsupported auth field type " + field.rustType);
  }
}

function authEncodeField(field: NativeField): string {
  const fieldName = "AuthRequest." + field.name;
  switch (field.rustType) {
    case "String":
      return (
        "encodePostcardString(value." +
        field.name +
        ", " +
        JSON.stringify(fieldName) +
        ")"
      );
    case "Option<Vec<String>>":
      return (
        "encodeOptionalScopes(value." +
        field.name +
        ", " +
        JSON.stringify(fieldName) +
        ")"
      );
    case "Option<String>":
      return (
        "encodeOptionalString(value." +
        field.name +
        ", " +
        JSON.stringify(fieldName) +
        ")"
      );
    default:
      return fail("unsupported auth request field type " + field.rustType);
  }
}

function parseAuthCallerDeadlines(
  rustSource: string,
): Readonly<Record<string, number>> {
  const values: Record<string, number> = {};
  for (const name of [
    "AUTH_BEGIN_CALL_DEADLINE_MS",
    "AUTH_TOKEN_CALL_DEADLINE_MS",
  ]) {
    const pattern = new RegExp(
      "^pub const " + name + ": u32 = ([0-9](?:_?[0-9])*);$",
      "gm",
    );
    const matches = [...rustSource.matchAll(pattern)];
    if (matches.length !== 1)
      fail(name + " needs one canonical Native u32 policy constant");
    const value = Number(matches[0][1].replaceAll("_", ""));
    if (!Number.isInteger(value) || value <= 0 || value > 0xffff_ffff)
      fail(name + " must be a positive u32");
    values[name] = value;
  }
  return values;
}

/** Generate only the approved auth DTOs/codecs and Native-owned caller defaults. */
export function renderAuthBinding(rustSource: string): string {
  const lines = rustSource.replaceAll("\r\n", "\n").split("\n");
  if (lines.some((line) => /^\s*#!\[/.test(line)))
    fail("native auth source-level attributes are not admitted");
  const request = parseNativeEnum(lines, "AuthRequest");
  const response = parseNativeEnum(lines, "AuthResponse");
  const deadlines = parseAuthCallerDeadlines(rustSource);
  const output = [
    "// @generated by packages/@keld/kipc/scripts/echo-codegen.ts.",
    "// Source: crates/keld-native/src/auth/mod.rs. Do not edit by hand.",
    "",
    'import { MAX_FRAME_LEN, decodeVarint, decodeU64Varint, encodeVarint, encodePostcardString, decodePostcardStringAt, kipcError } from "../../kipc/src/transport.ts";',
    "",
  ];
  for (const [name, variants] of [
    ["AuthRequest", request],
    ["AuthResponse", response],
  ] as const) {
    output.push("export type " + name + " =");
    for (const variant of variants) {
      const fields = variant.fields
        .map((field) => "; " + field.name + ": " + authFieldTsType(field))
        .join("");
      output.push(
        '  | { variant: "' +
          variant.name +
          '"' +
          fields +
          " }" +
          (variant === variants[variants.length - 1] ? ";" : ""),
      );
    }
    output.push("");
  }
  for (const name of Object.keys(deadlines))
    output.push("export const " + name + " = " + deadlines[name] + ";");
  output.push("", AUTH_RUNTIME, "");
  output.push(
    "/** Snapshot an auth request in Rust enum/field declaration order. */",
    "export function encodeAuthRequest(value: AuthRequest): Uint8Array {",
    '  if (!value || typeof value !== "object") throw kipcError("KELD-IPC-003", "AuthRequest must be an object");',
    "  let parts: Uint8Array[];",
    "  switch (value.variant) {",
  );
  request.forEach((variant, index) => {
    output.push(
      '    case "' +
        variant.name +
        '": parts = [encodeVarint(' +
        index +
        "), " +
        variant.fields.map(authEncodeField).join(", ") +
        "]; break;",
    );
  });
  output.push(
    '    default: throw kipcError("KELD-IPC-003", "unknown AuthRequest variant");',
    "  }",
    "  let length = 0;",
    "  for (const part of parts) {",
    "    length += part.byteLength;",
    '    if (length > MAX_FRAME_LEN) throw kipcError("KELD-IPC-003", "auth payload exceeds MAX_FRAME_LEN");',
    "  }",
    "  return Buffer.concat(parts, length);",
    "}",
    "",
    "/** Decode exact native success bytes, retaining the full u64 expiry domain. */",
    "export function decodeAuthResponse(payload: Uint8Array): AuthResponse {",
    '  if (!(payload instanceof Uint8Array) || payload.byteLength > MAX_FRAME_LEN) throw kipcError("KELD-IPC-003", "invalid AuthResponse payload envelope");',
    "  const [variant, afterVariant] = decodeVarint(payload, 0);",
    "  let offset = afterVariant;",
    "  let response: AuthResponse;",
    "  switch (variant) {",
  );
  response.forEach((variant, index) => {
    output.push("    case " + index + ": {");
    for (const field of variant.fields) {
      const decoder =
        field.rustType === "String"
          ? "decodePostcardStringAt"
          : field.rustType === "Vec<String>"
            ? "decodeStringVector"
            : field.rustType === "u64"
              ? "decodeU64Varint"
              : fail("unsupported auth response field type " + field.rustType);
      output.push(
        "      const [" +
          field.name +
          ", after_" +
          field.name +
          "] = " +
          decoder +
          "(payload, offset);",
        "      offset = after_" + field.name + ";",
      );
    }
    output.push(
      '      response = { variant: "' +
        variant.name +
        '"' +
        variant.fields.map((field) => ", " + field.name).join("") +
        " };",
      "      break;",
      "    }",
    );
  });
  output.push(
    '    default: throw kipcError("KELD-IPC-003", "unknown AuthResponse variant");',
    "  }",
    '  if (offset !== payload.byteLength) throw kipcError("KELD-IPC-003", "trailing bytes after AuthResponse");',
    "  return response;",
    "}",
    "",
  );
  return formatGenerated(output.join("\n"), authGeneratedPath);
}

/** Require the generated auth artifact to match the Native contract exactly. */
export function assertAuthArtifactFresh(
  rustSource: string,
  artifact: Uint8Array,
): void {
  if (
    !Buffer.from(artifact).equals(
      Buffer.from(renderAuthBinding(rustSource), "utf8"),
    )
  ) {
    fail("committed auth.generated.ts is stale; run bun run echo:generate");
  }
}

// ---------------------------------------------------------------------------
// Channel-table target (GH-508 spec docs/specs/gh508-kipc-channel-table.md §4.3).
//
// Reads the Rust channel table and rewrites one delimited region of the single
// staged transport file. Rust compilation (`validate_table`) is the validator
// of record; this parser admits only the rustfmt-normalized entry forms and
// fails closed, naming the source line, on anything else. It never guesses.
// ---------------------------------------------------------------------------

/** First line of the generated region; the rest of the line is its provenance. */
export const CHANNEL_REGION_BEGIN = "// @generated-begin channel-table";
/** Last line of the generated region. */
export const CHANNEL_REGION_END = "// @generated-end channel-table";

const ENTRY_HEADER = /^pub const ([A-Z][A-Z0-9_]*): ChannelEntry =(.*)$/;
const ENTRY_NAME = /^"([a-z][a-z0-9-]{0,31})"$/;
const ENTRY_ID = /^(?:0|[1-9][0-9]{0,4})$/;
const ENTRY_CLASS = /^ReceiveClass::[A-Z][A-Za-z0-9]*$/;
const CAPABILITY_PATH = "[A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)*";
const ENTRY_AUTHORITY = new RegExp(
  `^Authority::(?:HostInternal|Guarded\\(&\\[\\s*${CAPABILITY_PATH}(?:\\s*,\\s*${CAPABILITY_PATH})*\\s*,?\\s*\\]\\))$`,
);
const MAX_ENTRY_LINES = 32;

/** One parsed `pub const NAME: ChannelEntry` declaration. */
export interface ChannelTableEntry {
  /** Rust constant name, e.g. `ECHO`. */
  readonly rustName: string;
  /** Entry name, e.g. `echo`. */
  readonly name: string;
  /** Wire channel id. */
  readonly id: number;
  /** `ReceiveClass` variant, e.g. `HostCall`. */
  readonly receiveClass: string;
}

/** The parsed channel table in `CHANNEL_TABLE` order. */
export interface ChannelTable {
  /** `HANDSHAKE_CHANNEL`, reserved for `HELLO`. */
  readonly handshake: number;
  readonly entries: readonly ChannelTableEntry[];
  /** `ReceiveClass` variants for which `carries_host_events` is true. */
  readonly hostEventClasses: readonly string[];
}

interface SourceArgument {
  text: string;
  line: number;
}

function channelFail(line: number, detail: string): never {
  return fail(
    `crates/keld-ipc/src/channel_table.rs source line ${line}: ${detail}`,
  );
}

/** Splits call arguments at top-level commas, keeping each argument's source line. */
function splitArguments(segments: readonly SourceArgument[]): SourceArgument[] {
  const args: SourceArgument[] = [];
  let depth = 0;
  let inString = false;
  let current = "";
  let currentLine = segments[0]?.line ?? 0;
  for (const segment of segments) {
    for (let index = 0; index < segment.text.length; index += 1) {
      const char = segment.text[index];
      if (current.trim().length === 0) currentLine = segment.line;
      if (inString) {
        if (char === "\\") {
          current += char + (segment.text[index + 1] ?? "");
          index += 1;
          continue;
        }
        if (char === '"') inString = false;
      } else if (char === '"') {
        inString = true;
      } else if ("([{".includes(char)) {
        depth += 1;
      } else if (")]}".includes(char)) {
        depth -= 1;
      } else if (char === "," && depth === 0) {
        args.push({ text: current.trim(), line: currentLine });
        current = "";
        continue;
      }
      current += char;
    }
    current += " ";
  }
  if (current.trim().length !== 0)
    args.push({ text: current.trim(), line: currentLine });
  return args;
}

function parseEntry(
  lines: readonly string[],
  start: number,
): { entry: ChannelTableEntry; consumed: number } {
  const header = ENTRY_HEADER.exec(lines[start]);
  if (!header) {
    channelFail(
      start + 1,
      `unsupported ChannelEntry declaration: ${lines[start].trim()}`,
    );
  }
  const [, rustName, rest] = header;
  let segments: SourceArgument[];
  let consumed: number;
  const singleLine = /^ ChannelEntry::new\((.*)\);$/.exec(rest);
  if (singleLine) {
    segments = [{ text: singleLine[1], line: start + 1 }];
    consumed = 1;
  } else if (rest === "") {
    const wrapped = /^    ChannelEntry::new\((.*)\);$/.exec(
      lines[start + 1] ?? "",
    );
    if (!wrapped) {
      channelFail(
        start + 2,
        "expected the rustfmt-wrapped `    ChannelEntry::new(...);` line",
      );
    }
    segments = [{ text: wrapped[1], line: start + 2 }];
    consumed = 2;
  } else if (rest === " ChannelEntry::new(") {
    segments = [];
    let index = start + 1;
    for (; index < lines.length && lines[index] !== ");"; index += 1) {
      if (index - start > MAX_ENTRY_LINES)
        channelFail(start + 1, `unterminated ${rustName} entry`);
      if (!lines[index].startsWith("    ")) {
        channelFail(
          index + 1,
          `entry argument is not rustfmt-indented: ${lines[index].trim()}`,
        );
      }
      segments.push({ text: lines[index].trim(), line: index + 1 });
    }
    if (index >= lines.length)
      channelFail(start + 1, `unterminated ${rustName} entry`);
    consumed = index - start + 1;
  } else {
    return channelFail(
      start + 1,
      `unsupported ${rustName} initializer; use ChannelEntry::new(...)`,
    );
  }

  const args = splitArguments(segments);
  if (args.length !== 4) {
    channelFail(
      start + 1,
      `${rustName} must pass exactly 4 arguments to ChannelEntry::new`,
    );
  }
  const [nameArg, idArg, classArg, authorityArg] = args;
  const name = ENTRY_NAME.exec(nameArg.text);
  if (!name) {
    channelFail(
      nameArg.line,
      `entry name must be a "[a-z][a-z0-9-]{0,31}" string literal, found ${nameArg.text}`,
    );
  }
  if (!ENTRY_ID.test(idArg.text) || Number(idArg.text) > 0xffff) {
    channelFail(
      idArg.line,
      `channel id must be a decimal u16 literal, found ${idArg.text}`,
    );
  }
  if (!ENTRY_CLASS.test(classArg.text)) {
    channelFail(
      classArg.line,
      `receive class must be a ReceiveClass variant, found ${classArg.text}`,
    );
  }
  if (!ENTRY_AUTHORITY.test(authorityArg.text)) {
    channelFail(
      authorityArg.line,
      `authority must be Authority::HostInternal or Authority::Guarded(&[<keld_guard constant>, ...]), found ${authorityArg.text}`,
    );
  }
  const receiveClass = classArg.text.slice("ReceiveClass::".length);
  return {
    entry: { rustName, name: name[1], id: Number(idArg.text), receiveClass },
    consumed,
  };
}

function parseTableList(
  lines: readonly string[],
  start: number,
): { names: string[]; consumed: number } {
  const singleLine =
    /^pub const CHANNEL_TABLE: &\[ChannelEntry\] = &\[(.*)\];$/.exec(
      lines[start],
    );
  let raw: string[];
  let consumed: number;
  if (singleLine) {
    raw = singleLine[1].split(",").map((name) => name.trim());
    consumed = 1;
  } else if (lines[start] === "pub const CHANNEL_TABLE: &[ChannelEntry] = &[") {
    raw = [];
    let index = start + 1;
    for (; index < lines.length && lines[index] !== "];"; index += 1) {
      const item = /^    ([A-Z][A-Z0-9_]*),$/.exec(lines[index]);
      if (!item)
        channelFail(
          index + 1,
          `unsupported CHANNEL_TABLE item: ${lines[index].trim()}`,
        );
      raw.push(item[1]);
    }
    if (index >= lines.length)
      channelFail(start + 1, "unterminated CHANNEL_TABLE");
    consumed = index - start + 1;
  } else {
    return channelFail(
      start + 1,
      `unsupported CHANNEL_TABLE declaration: ${lines[start].trim()}`,
    );
  }
  for (const name of raw) {
    if (!/^[A-Z][A-Z0-9_]*$/.test(name))
      channelFail(
        start + 1,
        `CHANNEL_TABLE lists ${name}, which is not a constant name`,
      );
  }
  return { names: raw, consumed };
}

/** TypeScript name: the entry name uppercased, `-` mapped to `_`, plus `_CHANNEL`. */
export function channelConstantName(name: string): string {
  return `${name.toUpperCase().replaceAll("-", "_")}_CHANNEL`;
}

/**
 * The production lines of `channel_table.rs`: everything before its one
 * `#[cfg(test)] mod tests { ... }`, which must be the file's last item. Any other
 * `cfg` gate, anything after the test module and any block comment fails, so no
 * entry can sit where this parser does not read it.
 */
function productionLines(all: readonly string[]): readonly string[] {
  const gates = all.flatMap((line, index) =>
    /^\s*#\[cfg/.test(line) ? [index] : [],
  );
  if (
    gates.length > 1 ||
    (gates.length === 1 && all[gates[0]] !== "#[cfg(test)]")
  ) {
    channelFail(
      gates[gates.length === 1 ? 0 : 1] + 1,
      "only one `#[cfg(test)]`, gating the final `mod tests {`, is admitted",
    );
  }
  let production: readonly string[] = all;
  if (gates.length === 1) {
    const gate = gates[0];
    if (all[gate + 1] !== "mod tests {")
      channelFail(gate + 2, "the `#[cfg(test)]` gate must open `mod tests {`");
    const close = all.indexOf("}", gate + 2);
    if (close === -1) channelFail(gate + 2, "unterminated `mod tests {`");
    const trailing = all
      .slice(close + 1)
      .findIndex((line) => line.trim().length !== 0);
    if (trailing !== -1)
      channelFail(close + trailing + 2, "nothing may follow the test module");
    production = all.slice(0, gate);
  }
  production.forEach((line, index) => {
    if (line.includes("/*") || line.includes("*/"))
      channelFail(index + 1, "block comments are not admitted");
  });
  return production;
}

/** Parses the production half of `crates/keld-ipc/src/channel_table.rs`. */
export function parseChannelTable(rustSource: string): ChannelTable {
  const lines = productionLines(
    rustSource.replaceAll("\r\n", "\n").split("\n"),
  );
  let handshake: number | undefined;
  const entries = new Map<string, ChannelTableEntry>();
  let listed: string[] | undefined;
  let hostEventClasses: string[] | undefined;
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (/^\s*\/\//.test(line)) continue;
    if (line.startsWith("pub const HANDSHAKE_CHANNEL")) {
      const parsed =
        /^pub const HANDSHAKE_CHANNEL: ChannelId = ChannelId\((0|[1-9][0-9]{0,4})\);$/.exec(
          line,
        );
      if (!parsed || Number(parsed[1]) > 0xffff)
        channelFail(index + 1, `unsupported HANDSHAKE_CHANNEL: ${line.trim()}`);
      if (handshake !== undefined)
        channelFail(index + 1, "duplicate HANDSHAKE_CHANNEL");
      handshake = Number(parsed[1]);
    } else if (
      line === "    pub const fn carries_host_events(self) -> bool {"
    ) {
      // The Rust table owns which classes carry host EVENTs; read, never mirror.
      const body =
        /^        matches!\(self, (Self::[A-Z][A-Za-z0-9]*(?: \| Self::[A-Z][A-Za-z0-9]*)*)\)$/.exec(
          lines[index + 1] ?? "",
        );
      if (!body || lines[index + 2] !== "    }") {
        channelFail(
          index + 2,
          "carries_host_events must be one `matches!(self, Self::A | Self::B)` line",
        );
      }
      if (hostEventClasses !== undefined)
        channelFail(index + 1, "duplicate carries_host_events");
      hostEventClasses = body[1]
        .split(" | ")
        .map((variant) => variant.slice("Self::".length));
      index += 2;
    } else if (line.startsWith("pub const CHANNEL_TABLE")) {
      if (listed !== undefined)
        channelFail(index + 1, "duplicate CHANNEL_TABLE");
      const table = parseTableList(lines, index);
      listed = table.names;
      index += table.consumed - 1;
    } else if (/^pub const [A-Za-z0-9_]+: ChannelEntry\b/.test(line)) {
      const { entry, consumed } = parseEntry(lines, index);
      if (entries.has(entry.rustName))
        channelFail(index + 1, `duplicate entry constant ${entry.rustName}`);
      entries.set(entry.rustName, entry);
      index += consumed - 1;
    } else if (
      line.includes("ChannelEntry::new(") ||
      /\b(?:const|static)\s+[A-Za-z0-9_]+\s*:\s*ChannelEntry\b/.test(line)
    ) {
      channelFail(
        index + 1,
        `ChannelEntry outside the admitted pub const form: ${line.trim()}`,
      );
    }
  }
  if (handshake === undefined)
    fail("crates/keld-ipc/src/channel_table.rs: missing HANDSHAKE_CHANNEL");
  if (hostEventClasses === undefined)
    fail(
      "crates/keld-ipc/src/channel_table.rs: missing ReceiveClass::carries_host_events",
    );
  if (listed === undefined)
    fail("crates/keld-ipc/src/channel_table.rs: missing CHANNEL_TABLE");

  const ordered: ChannelTableEntry[] = [];
  for (const rustName of listed) {
    const entry = entries.get(rustName);
    if (!entry)
      fail(
        `CHANNEL_TABLE lists ${rustName}, which is not a parsed ChannelEntry constant`,
      );
    if (ordered.includes(entry))
      fail(`CHANNEL_TABLE lists ${rustName} more than once`);
    ordered.push(entry);
  }
  for (const rustName of entries.keys()) {
    if (!listed.includes(rustName))
      fail(`ChannelEntry constant ${rustName} is not listed in CHANNEL_TABLE`);
  }
  const names = new Set<string>();
  const constants = new Set<string>(["HANDSHAKE_CHANNEL"]);
  for (const entry of ordered) {
    if (names.has(entry.name))
      fail(`duplicate channel entry name ${entry.name}`);
    names.add(entry.name);
    const constant = channelConstantName(entry.name);
    if (constants.has(constant))
      fail(`entry ${entry.name} would generate a duplicate ${constant}`);
    constants.add(constant);
  }
  return { handshake, entries: ordered, hostEventClasses };
}

/** Renders the generated `transport.ts` region, markers included, without a trailing newline. */
export function renderChannelTableRegion(rustSource: string): string {
  const table = parseChannelTable(rustSource);
  const lines = [
    `${CHANNEL_REGION_BEGIN}: packages/@keld/kipc/scripts/echo-codegen.ts from`,
    "// crates/keld-ipc/src/channel_table.rs. Do not edit by hand; run bun run echo:generate.",
    "/** Reserved `HELLO` channel (`keld_ipc::channel_table::HANDSHAKE_CHANNEL`). */",
    `export const HANDSHAKE_CHANNEL = ${table.handshake};`,
  ];
  for (const entry of table.entries) {
    lines.push(
      `/** Channel \`${entry.name}\` (\`keld_ipc::channel_table::${entry.rustName}\`). */`,
    );
    lines.push(
      `export const ${channelConstantName(entry.name)} = ${entry.id};`,
    );
  }
  const allocated = table.entries.map((entry) =>
    channelConstantName(entry.name),
  );
  lines.push(
    "/** An allocated channel id (`keld_ipc::channel_table::CHANNEL_TABLE`). */",
    `export type AllocatedChannel = ${allocated.map((name) => `typeof ${name}`).join(" | ")};`,
    "/** Every allocated channel id, in table order. */",
    `export const ALLOCATED_CHANNELS: readonly AllocatedChannel[] = Object.freeze([${allocated.join(", ")}]);`,
  );
  const eventChannels = table.entries
    .filter((entry) => table.hostEventClasses.includes(entry.receiveClass))
    .map((entry) => channelConstantName(entry.name));
  lines.push(
    "/** Channels whose receive class carries host `EVENT`s (`ReceiveClass::carries_host_events`). */",
    `export const HOST_EVENT_CHANNELS: readonly AllocatedChannel[] = Object.freeze([${eventChannels.join(", ")}]);`,
  );
  lines.push(CHANNEL_REGION_END);
  return formatGenerated(lines.join("\n"), transportPath).trimEnd();
}

/** Line bounds of the one generated region in `transportSource`. */
export function channelRegionBounds(transportSource: string): {
  lines: string[];
  begin: number;
  end: number;
} {
  const lines = transportSource.split("\n");
  const begins = lines.flatMap((line, index) =>
    line.startsWith(CHANNEL_REGION_BEGIN) ? [index] : [],
  );
  const ends = lines.flatMap((line, index) =>
    line.startsWith(CHANNEL_REGION_END) ? [index] : [],
  );
  if (begins.length !== 1 || ends.length !== 1 || begins[0] > ends[0]) {
    fail(
      "transport.ts must contain exactly one channel-table region: one `// @generated-begin channel-table` line before one `// @generated-end channel-table` line",
    );
  }
  return { lines, begin: begins[0], end: ends[0] };
}

/** Replaces the generated region of `transportSource` with `region`. */
export function replaceChannelTableRegion(
  transportSource: string,
  region: string,
): string {
  const { lines, begin, end } = channelRegionBounds(transportSource);
  return [...lines.slice(0, begin), region, ...lines.slice(end + 1)].join("\n");
}

/** Fails when the committed region is not byte-identical to the render of the Rust table. */
export function assertChannelTableRegionFresh(
  rustSource: string,
  transportSource: string,
): void {
  const { lines, begin, end } = channelRegionBounds(transportSource);
  if (
    lines.slice(begin, end + 1).join("\n") !==
    renderChannelTableRegion(rustSource)
  ) {
    fail("channel table region is stale; run bun run echo:generate");
  }
}

/** `transportSource` without its stamp line (#653); unchanged when it has none. */
export function unstampedTransport(transportSource: string): string {
  return transportSource.startsWith(TRANSPORT_STAMP_PREFIX)
    ? transportSource.slice(transportSource.indexOf("\n") + 1)
    : transportSource;
}

/** The transport with a fresh channel-table region, restamped over its final bytes. */
export function regenerateTransport(
  rustSource: string,
  transportSource: string,
): string {
  const region = renderChannelTableRegion(rustSource);
  return stampTransport(
    replaceChannelTableRegion(unstampedTransport(transportSource), region),
  );
}

const DIALOG_RUNTIME =
  '// @generated by packages/@keld/kipc/scripts/echo-codegen.ts.\n// Source: crates/keld-native/src/dialog.rs. Do not edit by hand.\nimport {\n  decodeVarint,\n  decodePostcardStringAt,\n  encodeVarint,\n  encodeU64Varint,\n  encodePostcardString,\n  kipcError,\n} from "../../kipc/src/transport.ts";\nimport type { WindowRef } from "./window-codec.ts";\n\nexport type MessageKind = "None" | "Info" | "Error" | "Question" | "Warning";\nexport interface MessageOptions {\n  message: string;\n  kind: MessageKind;\n  buttons: readonly string[];\n  default_id: number | null;\n  cancel_id: number | null;\n  normalize_access_keys: boolean;\n  title: string | null;\n  detail: string | null;\n  no_link: boolean;\n  checkbox_label: string | null;\n  checkbox_checked: boolean | null;\n}\nexport type OpenProperty = "OpenFile" | "OpenDirectory" | "MultiSelections";\nexport interface FileDialogFilter { name: string; extensions: readonly string[] }\nexport interface OpenDialogOptions { default_path: string | null; filters: readonly FileDialogFilter[]; properties: readonly OpenProperty[] }\nexport interface SaveDialogOptions { default_path: string | null; filters: readonly FileDialogFilter[]; security_scoped_bookmarks: boolean }\nexport type DialogRequestV1 =\n  | { variant: "Message"; nonce: bigint; parent: WindowRef | null; options: MessageOptions }\n  | { variant: "Cancel"; nonce: bigint }\n  | { variant: "Open"; nonce: bigint; parent: WindowRef | null; options: OpenDialogOptions }\n  | { variant: "Save"; nonce: bigint; parent: WindowRef | null; options: SaveDialogOptions };\nexport type DialogReplyV1 =\n  | { variant: "Message"; response: number; checkbox_checked: boolean }\n  | { variant: "Cancel"; disposition: "Requested" | "AlreadyCompleted" }\n  | { variant: "Open"; canceled: boolean; file_paths: string[] }\n  | { variant: "Save"; canceled: boolean; file_path: string };\n\nfunction invalid(detail: string): never {\n  throw kipcError("KELD-IPC-003", detail);\n}\nfunction booleanByte(value: boolean): Uint8Array {\n  if (typeof value !== "boolean") return invalid("dialog boolean is invalid");\n  return new Uint8Array([value ? 1 : 0]);\n}\nfunction optional<T>(\n  value: T | null,\n  encode: (item: T) => Uint8Array,\n): Uint8Array {\n  if (value === null) return new Uint8Array([0]);\n  return Buffer.concat([new Uint8Array([1]), encode(value)]);\n}\nfunction text(value: string): Uint8Array {\n  if (typeof value !== "string" || Buffer.byteLength(value, "utf8") > 16 * 1024)\n    return invalid("dialog text is invalid");\n  return encodePostcardString(value, "dialog text");\n}\nfunction index(value: number): Uint8Array {\n  if (!Number.isInteger(value) || value < 0 || value > 0xffffffff)\n    return invalid("dialog button index is invalid");\n  return encodeVarint(value);\n}\n/** Encode only pinned legacy path-only options; no filesystem authority is minted. */\nfunction fileText(value: unknown, limit: number, field: string): Uint8Array {\n  if (typeof value !== "string" || Buffer.byteLength(value, "utf8") > limit || value.includes("\\0"))\n    return invalid(field + " exceeds its bounded UTF-8 grammar");\n  return encodePostcardString(value, field);\n}\nfunction filtersField(value: readonly FileDialogFilter[]): Uint8Array {\n  if (!Array.isArray(value) || value.length > 32) return invalid("too many file filter groups");\n  const parts: Uint8Array[] = [encodeVarint(value.length)];\n  for (const filter of value) {\n    if (!filter || typeof filter !== "object" || typeof filter.name !== "string" ||\n        filter.name.length === 0 || filter.name.includes("\\0") ||\n        Buffer.byteLength(filter.name, "utf8") > 256 ||\n        !Array.isArray(filter.extensions) || filter.extensions.length === 0 || filter.extensions.length > 32)\n      return invalid("invalid file filter group");\n    parts.push(fileText(filter.name, 256, "file filter name"), encodeVarint(filter.extensions.length));\n    const seen = new Set<string>();\n    for (const ext of filter.extensions) {\n      if (typeof ext !== "string" || ext.length === 0 || Buffer.byteLength(ext, "utf8") > 128 ||\n          ext.startsWith(".") || (ext !== "*" && [...ext].some(ch => ch === "*" || ch === "/" || ch === "\\\\" || (ch.charCodeAt(0) < 32 || (ch.charCodeAt(0) >= 0x7f && ch.charCodeAt(0) <= 0x9f)))) || seen.has(ext))\n        return invalid("invalid or repeated file filter extension");\n      seen.add(ext);\n      parts.push(fileText(ext, 128, "file extension"));\n    }\n    if (seen.has("*") && seen.size !== 1) return invalid("all-file extension group must stand alone");\n  }\n  return Buffer.concat(parts);\n}\nfunction fileOptions(kind: "Open" | "Save", value: OpenDialogOptions | SaveDialogOptions): Uint8Array {\n  if (!value || typeof value !== "object") return invalid("file dialog options object missing");\n  const parts: Uint8Array[] = [optional(value.default_path, path => fileText(path, 4096, "default path")), filtersField(value.filters)];\n  if (kind === "Open") {\n    const props = (value as OpenDialogOptions).properties;\n    if (!Array.isArray(props) || props.length > 3 || new Set(props).size !== props.length) return invalid("invalid Open properties");\n    const ids = ["OpenFile", "OpenDirectory", "MultiSelections"];\n    parts.push(encodeVarint(props.length));\n    for (const prop of props) {\n      const id = ids.indexOf(prop);\n      if (id < 0) return invalid("unknown Open property");\n      parts.push(encodeVarint(id));\n    }\n  } else {\n    const bookmark = (value as SaveDialogOptions).security_scoped_bookmarks;\n    if (bookmark !== false) return invalid("security scoped bookmark cannot mint a capability");\n    parts.push(booleanByte(bookmark));\n  }\n  const bytes = Buffer.concat(parts);\n  if (bytes.byteLength > 16 * 1024) return invalid("file dialog options exceed bounded envelope");\n  return bytes;\n}\nfunction selectedFilePath(value: string): boolean {\n  return Buffer.byteLength(value, "utf8") <= 4096 && value.startsWith("/") &&\n    !value.includes("\\0") && !value.includes("\\\\") && !value.split("/").includes("..");\n}\n\n/** Snapshot one bounded request in Native\'s postcard declaration order. */\nexport function encodeDialogRequest(value: DialogRequestV1): Uint8Array {\n  if (\n    typeof value !== "object" ||\n    value === null ||\n    typeof value.nonce !== "bigint" ||\n    value.nonce <= 0n\n  )\n    return invalid("invalid dialog request or nonce");\n  const nonce = encodeU64Varint(value.nonce);\n  if (value.variant === "Cancel")\n    return Buffer.concat([new Uint8Array([1]), nonce]);\n  if (value.variant === "Open" || value.variant === "Save") {\n    const options = fileOptions(value.variant, value.options);\n    const parent = optional(value.parent, ref => Buffer.concat([index(ref.id), encodeU64Varint(ref.incarnation)]));\n    return Buffer.concat([new Uint8Array([value.variant === "Open" ? 2 : 3]), nonce, parent, options]);\n  }\n  if (value.variant !== "Message")\n    return invalid("unknown dialog request variant");\n  const o = value.options;\n  if (\n    !o ||\n    typeof o !== "object" ||\n    !Array.isArray(o.buttons) ||\n    o.buttons.length > 16\n  )\n    return invalid("invalid dialog options or button count");\n  const kind = ["None", "Info", "Error", "Question", "Warning"].indexOf(o.kind);\n  if (kind < 0) return invalid("unknown dialog message kind");\n  const count = Math.max(o.buttons.length, 1);\n  if (\n    (o.default_id !== null && o.default_id >= count) ||\n    (o.cancel_id !== null && o.cancel_id >= count)\n  )\n    return invalid("dialog button index is out of range");\n  if (\n    o.checkbox_checked !== null &&\n    (o.checkbox_label === null || o.checkbox_label === "")\n  )\n    return invalid("dialog checkbox requires a nonempty label");\n  const parts: Uint8Array[] = [];\n  let length = 0;\n  const append = (part: Uint8Array): void => {\n    length += part.byteLength;\n    if (length > 16 * 1024)\n      invalid("dialog options exceed the bounded envelope");\n    parts.push(part);\n  };\n  append(text(o.message));\n  append(encodeVarint(kind));\n  append(encodeVarint(o.buttons.length));\n  for (const button of o.buttons) append(text(button));\n  append(optional(o.default_id, index));\n  append(optional(o.cancel_id, index));\n  append(booleanByte(o.normalize_access_keys));\n  append(optional(o.title, text));\n  append(optional(o.detail, text));\n  append(booleanByte(o.no_link));\n  append(optional(o.checkbox_label, text));\n  append(optional(o.checkbox_checked, booleanByte));\n  const options = Buffer.concat(parts, length);\n  const parent = optional(value.parent, (ref) =>\n    Buffer.concat([index(ref.id), encodeU64Varint(ref.incarnation)]),\n  );\n  return Buffer.concat([new Uint8Array([0]), nonce, parent, options]);\n}\n/** Decode a complete Native reply; correlation and result context remain Host-owned. */\nexport function decodeDialogReply(payload: Uint8Array): DialogReplyV1 {\n  if (!(payload instanceof Uint8Array)) return invalid("invalid dialog reply");\n  const [variant, start] = decodeVarint(payload, 0);\n  const [first, end] = decodeVarint(payload, start);\n  if (variant === 0) {\n    if (\n      end >= payload.length ||\n      (payload[end] !== 0 && payload[end] !== 1) ||\n      end + 1 !== payload.length\n    )\n      return invalid("invalid dialog message reply");\n    return {\n      variant: "Message",\n      response: first,\n      checkbox_checked: payload[end] === 1,\n    };\n  }\n  if (variant === 1 && end === payload.length && first <= 1)\n    return {\n      variant: "Cancel",\n      disposition: first === 0 ? "Requested" : "AlreadyCompleted",\n    };\n  if (variant === 2) {\n    if (payload.byteLength > 256 * 1024 || first > 1) return invalid("invalid native Open Cancel value");\n    const [length, afterCount] = decodeVarint(payload, end);\n    if (length > 32) return invalid("native Open selected too many paths");\n    let offset = afterCount;\n    const file_paths: string[] = [];\n    for (let i = 0; i < length; i++) {\n      const [path, next] = decodePostcardStringAt(payload, offset);\n      if (!selectedFilePath(path)) return invalid("native Open selected an invalid path");\n      file_paths.push(path);\n      offset = next;\n    }\n    if (offset !== payload.length || (first === 1 && file_paths.length !== 0) || (first === 0 && file_paths.length === 0))\n      return invalid("native Open canceled/selected path mismatch");\n    return { variant: "Open", canceled: first === 1, file_paths };\n  }\n  if (variant === 3) {\n    if (payload.byteLength > 256 * 1024 || first > 1) return invalid("invalid native Save Cancel value");\n    const [file_path, after] = decodePostcardStringAt(payload, end);\n    if (after !== payload.length || (first === 1 ? file_path !== "" : !selectedFilePath(file_path)))\n      return invalid("native Save canceled/selected path mismatch");\n    return { variant: "Save", canceled: first === 1, file_path };\n  }\n  return invalid("invalid dialog reply variant or disposition");\n}\n';

/** The dialog binding admits only the exact Rust-owned postcard schema. */
export function renderDialogBinding(rustSource: string): string {
  const source = rustSource
    .replaceAll("\r\n", "\n")
    .replace(/^\s*\/\/\/.*$/gm, "");
  if ([...source.matchAll(/#\s*\[\s*serde\s*\(/g)].length !== 5)
    fail("dialog schema has unsupported serde attributes");
  const definitions: readonly [string, string][] = [
    ["enum MessageKind", "None,Info,Error,Question,Warning,"],
    [
      "struct MessageOptions",
      'pub message:String,pub kind:MessageKind,#[serde(deserialize_with="deserialize_buttons")]pub buttons:Vec<String>,pub default_id:Option<u32>,pub cancel_id:Option<u32>,pub normalize_access_keys:bool,pub title:Option<String>,pub detail:Option<String>,pub no_link:bool,pub checkbox_label:Option<String>,pub checkbox_checked:Option<bool>,',
    ],
    [
      "struct FileDialogFilter",
      'pub name:String,#[serde(deserialize_with="deserialize_file_extensions")]pub extensions:Vec<String>,',
    ],
    ["enum OpenProperty", "OpenFile,OpenDirectory,MultiSelections,"],
    [
      "struct OpenDialogOptions",
      'pub default_path:Option<String>,#[serde(deserialize_with="deserialize_file_filters")]pub filters:Vec<FileDialogFilter>,#[serde(deserialize_with="deserialize_open_properties")]pub properties:Vec<OpenProperty>,',
    ],
    [
      "struct SaveDialogOptions",
      'pub default_path:Option<String>,#[serde(deserialize_with="deserialize_file_filters")]pub filters:Vec<FileDialogFilter>,pub security_scoped_bookmarks:bool,',
    ],
    [
      "enum DialogRequestV1",
      "Message{nonce:u64,parent:Option<WindowRef>,options:MessageOptions,},Cancel{nonce:u64,},Open{nonce:u64,parent:Option<WindowRef>,options:OpenDialogOptions,},Save{nonce:u64,parent:Option<WindowRef>,options:SaveDialogOptions,},",
    ],
    ["enum CancelDisposition", "Requested,AlreadyCompleted,"],
    [
      "enum DialogReplyV1",
      "Message{response:u32,checkbox_checked:bool,},Cancel{disposition:CancelDisposition,},Open{canceled:bool,file_paths:Vec<String>,},Save{canceled:bool,file_path:String,},",
    ],
  ];
  for (const [name, expected] of definitions) {
    const pattern = new RegExp("^pub " + name + " \\{([\\s\\S]*?)^\\}", "gm");
    const matches = [...source.matchAll(pattern)];
    if (
      matches.length !== 1 ||
      !source
        .slice(0, matches[0].index)
        .trimEnd()
        .endsWith(
          name === "enum OpenProperty"
            ? "#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]"
            : name === "enum MessageKind" || name === "enum CancelDisposition"
              ? "#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]"
              : "#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]",
        ) ||
      matches[0][1].replace(/\s+/g, "") !== expected.replace(/\s+/g, "")
    )
      fail("dialog schema differs at " + name);
  }
  if (
    !source.includes(
      "pub const MAX_DIALOG_OPTIONS_BYTES: usize = 16 * 1024;",
    ) ||
    !source.includes("pub const MAX_DIALOG_BUTTONS: usize = 16;") ||
    !source.includes("pub const MAX_DIALOG_PATHS: usize = 32;") ||
    !source.includes("pub const MAX_DIALOG_FILTERS: usize = 32;") ||
    !source.includes("pub const MAX_DIALOG_RESPONSE_BYTES: usize = 256 * 1024;")
  )
    fail("dialog bounds differ from the admitted schema");
  return formatGenerated(DIALOG_RUNTIME, dialogGeneratedPath);
}

function generate(): void {
  const fsGenerated = renderFsBinding(readFileSync(fsSourcePath, "utf8"));
  const authGenerated = renderAuthBinding(readFileSync(authSourcePath, "utf8"));
  const dialogGenerated = renderDialogBinding(
    readFileSync(dialogSourcePath, "utf8"),
  );
  const rustSource = readFileSync(rustSourcePath, "utf8");
  const outputs = generatedPaths.map((path) => ({
    path,
    source: renderEchoDeclarations(rustSource, path),
  }));
  const regenerated = regenerateTransport(
    readFileSync(channelTableSourcePath, "utf8"),
    readFileSync(transportPath, "utf8"),
  );
  verifyTransportStamp(Buffer.from(regenerated), transportPath);
  outputs.push(
    { path: fsGeneratedPath, source: fsGenerated },
    { path: authGeneratedPath, source: authGenerated },
    { path: dialogGeneratedPath, source: dialogGenerated },
    { path: transportPath, source: regenerated },
  );
  // All parsing, formatting and stamping must succeed before the first write.
  // This does not make filesystem write errors a multi-file transaction.
  for (const { path, source } of outputs) writeFileSync(path, source, "utf8");
}

function check(): void {
  if (
    !Buffer.from(readFileSync(dialogGeneratedPath)).equals(
      Buffer.from(renderDialogBinding(readFileSync(dialogSourcePath, "utf8"))),
    )
  )
    fail("committed dialog.generated.ts is stale; run bun run echo:generate");
  assertAuthArtifactFresh(
    readFileSync(authSourcePath, "utf8"),
    readFileSync(authGeneratedPath),
  );
  assertFsArtifactFresh(
    readFileSync(fsSourcePath, "utf8"),
    readFileSync(fsGeneratedPath),
  );
  const rustSource = readFileSync(rustSourcePath, "utf8");
  for (const path of generatedPaths) {
    let actual: Buffer;
    try {
      actual = readFileSync(path);
    } catch (error) {
      fail(`cannot read ${path}: ${String(error)}; run bun run echo:generate`);
    }
    assertEchoArtifactFresh(rustSource, actual, path);
  }
  assertChannelTableRegionFresh(
    readFileSync(channelTableSourcePath, "utf8"),
    readFileSync(transportPath, "utf8"),
  );
  try {
    verifyTransportStamp(
      readFileSync(transportPath),
      "packages/@keld/kipc/src/transport.ts",
    );
  } catch (error) {
    fail(
      `transport stamp is stale; run bun run echo:generate (${error instanceof Error ? error.message : String(error)})`,
    );
  }
}

if (import.meta.main) {
  try {
    const [command, ...extra] = process.argv.slice(2);
    if (extra.length !== 0 || (command !== "generate" && command !== "check")) {
      fail("usage: bun run scripts/echo-codegen.ts <generate|check>");
    }
    if (command === "generate") generate();
    else check();
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}
